function size(canvas,context){let r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);canvas.width=Math.max(1,Math.round(r.width*d));canvas.height=Math.max(1,Math.round(r.height*d));context.setTransform(d,0,0,d,0,0);return {w:r.width,h:r.height}}
