function updateControlValues(){for(const input of $('atlas-controls').querySelectorAll('[data-key]')){const k=input.dataset.key,v=cfg[active][k];input.value=v;if(input.type==='range'){const out=$('atlas-controls').querySelector(`[data-value="${k}"]`);if(out)out.textContent=fmt(k,v)}}if(active==='thunder'){$('thunder-delay').innerHTML=(cfg.thunder.distance*1000/C).toFixed(2)+' <small>seconds after the flash</small>'}}
