async function getContext(){if(!context){context=new (window.AudioContext||window.webkitAudioContext)();gain=context.createGain();gain.gain.value=muted?0:Number($('atlas-volume').value)/100;gain.connect(context.destination)}await context.resume();if(context.state!=='running')throw Error('Browser audio is suspended; press Listen to try again.')}
