function updatePlaybackUI(){if(!data)return;const time=playing?current():offset,arr=data.arrival;$('atlas-clock').textContent=active==='thunder'?'T +'+time.toFixed(2)+' s':time.toFixed(2)+' s';$('atlas-scrub').value=time/data.duration*1000;$('atlas-play-icon').textContent=playing?'Ⅱ':'▶';$('atlas-play-label').textContent=playing?'Pause':active==='designer'?'Play note':offset>0&&offset<data.duration?'Resume':'Listen';if(active==='thunder')$('atlas-state').textContent=arr==null?'READY':time<arr?'WAITING FOR THUNDER':time<arr+(data.rumbleDuration||0)?'THUNDER ROLLING':'THUNDER PASSED';else if(active==='doppler')$('atlas-state').textContent=time<data.duration*.45?'SOURCE APPROACHING':time<data.duration*.55?'PASSING':'SOURCE RECEDING';else if(active==='beats')$('atlas-state').textContent='BEAT RATE '+cfg.beats.beat+' HZ';else $('atlas-state').textContent=playing?'PLAYING':'READY';updateReading()}
