function text(ctx,s,x,y,color='#9db2bb',align='left',size=12){ctx.font=`${size}px "DM Sans",sans-serif`;ctx.fillStyle=color;ctx.textAlign=align;ctx.fillText(s,x,y)}function line(ctx,x,y,X,Y,color='#34464e',width=1,dash=[]){ctx.beginPath();ctx.setLineDash(dash);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.moveTo(x,y);ctx.lineTo(X,Y);ctx.stroke();ctx.setLineDash([])}function background(ctx,w,h){ctx.fillStyle='#0c171d';ctx.fillRect(0,0,w,h);const step=44;for(let x=0;x<w;x+=step)line(ctx,x,0,x,h,'#172931');for(let y=0;y<h;y+=step)line(ctx,0,y,w,y,'#172931')}
function drawDoppler(ctx,w,h,time){const ground=h*.77,py=h*.36,ox=w*.49,v=cfg.doppler.speed/3.6,travel=Math.max(7,data?.duration||9),scale=(w*.7)/(v*travel),x=ox+v*time*scale;ctx.save();ctx.beginPath();ctx.rect(0,0,w,ground);ctx.clip();for(let j=1;j<=15;j++){let age=j*.23,r=343*age*scale,cx=ox+v*(time-age)*scale;if(r>3){ctx.beginPath();ctx.arc(cx,py,r,0,Math.PI*2);ctx.strokeStyle=`rgba(101,200,213,${.09+.19*Math.exp(-age/2.5)})`;ctx.stroke()}}ctx.restore();line(ctx,0,ground,w,ground,'#667b80');let xx=Math.max(26,Math.min(w-26,x));ctx.fillStyle='#eff4ef';ctx.beginPath();ctx.moveTo(xx+25,py);ctx.lineTo(xx-18,py-11);ctx.lineTo(xx-14,py);ctx.lineTo(xx-18,py+11);ctx.fill();text(ctx,cfg.doppler.source==='race'?'RACE CAR':cfg.doppler.source==='train'?'TRAIN':'SIREN',xx,py-24,'#c2f881','center',10);ctx.beginPath();ctx.arc(ox,ground-6,5,0,Math.PI*2);ctx.fillStyle='#f0f4f2';ctx.fill();text(ctx,'LISTENER',ox,ground+18,'#9db2bb','center',10);text(ctx,`PASS SPEED ${cfg.doppler.speed} km/h`,16,h-14,'#7f9aa5','left',10)}
function drawEcho(ctx,w,h,time){const pad=38,roomW=w-2*pad,roomH=h-80,top=34,left=pad,bot=top+roomH,right=left+roomW;ctx.strokeStyle='#526c73';ctx.lineWidth=2;ctx.strokeRect(left,top,roomW,roomH);const sx=left+roomW*.24,ly=top+roomH*.57,lx=left+roomW*.72;ctx.fillStyle='#f3b786';ctx.fillRect(sx-7,top+roomH*.52,14,14);ctx.fillStyle='#c2f881';ctx.beginPath();ctx.arc(lx,ly,6,0,Math.PI*2);ctx.fill();text(ctx,'SOUND',sx,top+roomH*.52-12,'#f3b786','center',10);text(ctx,'LISTENER',lx,ly+23,'#c2f881','center',10);const L=Number(cfg.echo.length),W=Number(cfg.echo.width),H=Number(cfg.echo.height),rt=data?.rt60??roomReverbTime(L,W,H,cfg.echo.absorption);let timeNow=time;for(let i=0;i<6;i++){let n=i+1,d=(L*.5+n*W*.24)/343,xMirror=sx+(n%2?right-sx:sx-left),arrival=d;let vis=playing?Math.max(0,1-Math.abs(timeNow-arrival)/.20):1;if(vis>.02){line(ctx,sx,top+roomH*.52,xMirror,top+roomH*.52,`rgba(101,200,213,${.25+.65*vis})`,1.5,[5,5]);line(ctx,xMirror,top+roomH*.52,lx,ly,`rgba(194,248,129,${.12+.55*vis})`,1,[4,5])}}text(ctx,`ROOM DECAY · RT₆₀ ${rt.toFixed(2)} s`,w/2,h-16,'#91aab4','center',11)}
function drawUnderwater(ctx,w,h){const surface=h*.24,sea=h*.86;let g=ctx.createLinearGradient(0,surface,0,sea);g.addColorStop(0,'#163a50');g.addColorStop(1,'#081824');ctx.fillStyle=g;ctx.fillRect(0,surface,w,sea-surface);line(ctx,0,surface,w,surface,'#67c5df',2);text(ctx,'SEA SURFACE',12,surface-9,'#7bd8ef','left',10);const sx=w*.28,sy=surface+(sea-surface)*.64,lx=w*.73,ly=surface+(sea-surface)*.48;ctx.beginPath();ctx.arc(sx,sy,9,0,Math.PI*2);ctx.fillStyle='#8ee0ea';ctx.fill();ctx.beginPath();ctx.arc(lx,ly,6,0,Math.PI*2);ctx.fillStyle='#c2f881';ctx.fill();text(ctx,cfg.underwater.source.toUpperCase(),sx,sy+25,'#9fcbd1','center',10);text(ctx,'HYDROPHONE',lx,ly+22,'#c2f881','center',10);for(let i=1;i<=5;i++){let x=sx+(lx-sx)*i/5,y=sy+(ly-sy)*i/5,r=i*26;ctx.beginPath();ctx.ellipse(x,y,r,r*.43,-.16,0,Math.PI*2);ctx.strokeStyle=`rgba(94,198,218,${.42-i*.055})`;ctx.stroke()}const deep=sea+10;ctx.fillStyle='#152d31';ctx.fillRect(0,sea,w,h-sea);text(ctx,`DISTANCE ${cfg.underwater.distance.toFixed(1)} km  ·  DEPTH ${Number(cfg.underwater.depth).toLocaleString()} m`,w/2,h-16,'#9eb6af','center',10);line(ctx,0,sea,w,sea,'#365158')}
function drawBeats(ctx,w,h,time){const sep=Math.min(w*.28,56+Number(cfg.beats.spacing)*10),x1=w/2-sep,x2=w/2+sep,y0=h*.45,cols=100,rows=48,cellW=w/cols,cellH=(h-48)/rows,f1=Number(cfg.beats.f1),f2=f1+Number(cfg.beats.beat),image=ctx.createImageData(cols,rows);for(let j=0;j<rows;j++)for(let i=0;i<cols;i++){const x=(i+.5)*w/cols, y=19+(j+.5)*(h-48)/rows,r1=Math.max(12,Math.hypot(x-x1,y-y0)),r2=Math.max(12,Math.hypot(x-x2,y-y0)),v=Math.sin(2*Math.PI*f1*(time-r1/343))+Math.sin(2*Math.PI*f2*(time-r2/343)),amp=Math.min(1,Math.abs(v)*.62),ix=(j*cols+i)*4;if(v>0){image.data[ix]=48;image.data[ix+1]=120+Math.round(90*amp);image.data[ix+2]=145+Math.round(90*amp)}else{image.data[ix]=115+Math.round(100*amp);image.data[ix+1]=173+Math.round(70*amp);image.data[ix+2]=60}image.data[ix+3]=225}const off=document.createElement('canvas');off.width=cols;off.height=rows;off.getContext('2d').putImageData(image,0,0);ctx.save();ctx.imageSmoothingEnabled=true;ctx.drawImage(off,0,18,w,h-48);ctx.restore();for(const [x,col,l] of [[x1,'#65c8d5','A'],[x2,'#c2f881','B']]){ctx.beginPath();ctx.arc(x,y0,6,0,Math.PI*2);ctx.fillStyle=col;ctx.fill();text(ctx,l,x,y0-13,col,'center',11)}const obsX=w/2+Number(cfg.beats.position)*w*.38,obsY=y0+(h-50)*.31;ctx.beginPath();ctx.arc(obsX,obsY,6,0,Math.PI*2);ctx.fillStyle='#f3b786';ctx.fill();text(ctx,'YOU',obsX,obsY+20,'#f3b786','center',10);const beat=Number(cfg.beats.beat);text(ctx,beat===0?'SAME PITCH · STEADY LEVEL':`${beat} beats per second`,w/2,h-14,'#9eb6bf','center',12)}
function drawThunder(ctx,w,h,time){const sky=h*.68;const grad=ctx.createLinearGradient(0,0,0,sky);grad.addColorStop(0,'#17202d');grad.addColorStop(1,'#263447');ctx.fillStyle=grad;ctx.fillRect(0,0,w,sky);ctx.fillStyle='#0b141a';ctx.fillRect(0,sky,w,h-sky);ctx.fillStyle='#46505a';ctx.beginPath();ctx.ellipse(w*.29,sky*.25,w*.25,27,0,0,Math.PI*2);ctx.ellipse(w*.46,sky*.23,w*.22,35,0,0,Math.PI*2);ctx.fill();const bolt=Math.min(1,Math.max(0,(time||0)/.35));if(time<.55){ctx.strokeStyle='#ecf7ff';ctx.lineWidth=2+bolt*2;ctx.beginPath();ctx.moveTo(w*.4,sky*.24);ctx.lineTo(w*.36,sky*.44);ctx.lineTo(w*.42,sky*.42);ctx.lineTo(w*.33,sky*.71);ctx.stroke();if(bolt>0){ctx.fillStyle=`rgba(201,226,255,${(1-bolt)*.26})`;ctx.fillRect(0,0,w,h)}}line(ctx,0,sky,w,sky,'#536568');let obs=w*.79;ctx.fillStyle='#c2f881';ctx.beginPath();ctx.arc(obs,sky-8,5,0,Math.PI*2);ctx.fill();line(ctx,obs,sky-3,obs,sky+18,'#c2f881',2);text(ctx,`${cfg.thunder.distance.toFixed(1)} km`,obs,sky+38,'#d6e2d9','center',11);text(ctx,`SOUND SPEED ${C} m/s`,w/2,h-14,'#9eb6bf','center',10)}
function drawDesigner(ctx,w,h,time){if(!data){text(ctx,'PREPARING YOUR PATCH',w/2,h/2,'#94abb4','center',13);return}const samples=data.samples,sr=data.sampleRate,mid=h*.48,scale=h*.29,win=Math.min(samples.length,Math.floor(sr*.055));line(ctx,0,mid,w,mid,'#38505a');ctx.beginPath();ctx.strokeStyle='#c2f881';ctx.lineWidth=2;for(let x=0;x<w;x++){const i=Math.floor(x/w*win),y=mid-samples[i]*scale;if(!x)ctx.moveTo(x,y);else ctx.lineTo(x,y)}ctx.stroke();text(ctx,`${cfg.designer.wave.toUpperCase()} WAVEFORM`,14,28,'#93aab4','left',10);const bins=48,base=h*.89;for(let b=1;b<=bins;b++){const freq=b*sr/(2*bins),cut=Number(cfg.designer.cutoff),col=Math.min(1,Math.max(.08,Math.exp(-freq/cut)));const mag=cfg.designer.wave==='sine'?(b===1?1:.015):cfg.designer.wave==='square'&&b%2===0?.02:cfg.designer.wave==='triangle'&&b%2===0?.02:1/b;const ht=Math.min(h*.27,mag*col*h*.48);ctx.fillStyle=b<bins/8?'#65c8d5':'#c2f881';ctx.fillRect(12+(w-24)*(b-1)/bins,base-ht,Math.max(2,(w-24)/bins-2),ht)}text(ctx,'HARMONIC SPECTRUM',14,h*.66,'#93aab4','left',10);text(ctx,'0 Hz',12,h-8,'#8198a2','left',9);text(ctx,`${Math.round(SAMPLE_RATE/2/1000)} kHz`,w-12,h-8,'#8198a2','right',9)}
function drawScene(){const {w,h}=sceneBox;if(!w||!h)return;background(sceneContext,w,h);const time=playing?current():offset;if(active==='doppler')drawDoppler(sceneContext,w,h,time-3);else if(active==='echo')drawEcho(sceneContext,w,h,time);else if(active==='underwater')drawUnderwater(sceneContext,w,h);else if(active==='beats')drawBeats(sceneContext,w,h,time);else if(active==='thunder')drawThunder(sceneContext,w,h,time);else if(active==='designer')drawDesigner(sceneContext,w,h,time);$('atlas-scene-caption').textContent=active==='doppler'?'Wavefront spacing records the moving source’s pitch shift.':active==='echo'?'Dashed paths show early wall reflections; the room keeps the sound ringing.':active==='underwater'?'Higher frequencies fade faster in seawater.':active==='beats'?'Where the rings meet, pressure adds. Between them, it cancels.':active==='thunder'?'The light arrives first. Sound crosses the distance at 343 m/s.':'One oscillator. One filter. A spectrum built from the waveform.'}
function drawTrace(){const {w,h}=traceBox;if(!w||!h||!data)return;traceContext.clearRect(0,0,w,h);const top=22,bot=h-20,mid=(top+bot)/2;for(let i=0;i<=8;i++)line(traceContext,w*i/8,top,w*i/8,bot,'#243841');line(traceContext,0,mid,w,mid,'#344b54');const samples=active==='doppler'&&data.samplesL?data.samplesL:data.samples;const peak=Math.max(.02,data.peak||0);if(active==='underwater'&&data.attenuation){const max=Math.max(1,...data.attenuation.map(x=>x.dbKm));traceContext.beginPath();traceContext.strokeStyle='#65c8d5';for(let i=0;i<data.attenuation.length;i++){const q=data.attenuation[i],x=i/(data.attenuation.length-1)*w,y=bot-q.dbKm/max*(bot-top)*.8;if(!i)traceContext.moveTo(x,y);else traceContext.lineTo(x,y)}traceContext.stroke();text(traceContext,'FREQUENCY-DEPENDENT LOSS',8,top+10,'#9eb6bf','left',9);text(traceContext,'LOW',5,bot,'#9eb6bf','left',9);text(traceContext,'HIGH',w-5,bot,'#9eb6bf','right',9);return}
 if(active==='echo'&&data.impulses){for(const e of data.impulses){const x=e.delay/data.duration*w;line(traceContext,x,top,x,bot,`rgba(101,200,213,${Math.min(.9,.12+e.gain*.9)})`,Math.max(1,e.gain*2));}}
 if(samples){traceContext.beginPath();traceContext.strokeStyle=active==='thunder'?'#f3b786':'#c2f881';traceContext.lineWidth=1;const step=Math.max(1,Math.floor(samples.length/w));for(let x=0;x<w;x++){const a=Math.floor(x/w*samples.length),b=Math.min(samples.length,a+step);let lo=0,hi=0;for(let i=a;i<b;i++){lo=Math.min(lo,samples[i]);hi=Math.max(hi,samples[i])}traceContext.moveTo(x,mid-hi/peak*(bot-top)*.42);traceContext.lineTo(x,mid-lo/peak*(bot-top)*.42)}traceContext.stroke()}
 if(active==='thunder'&&data.arrival!==null)line(traceContext,data.arrival/data.duration*w,top,data.arrival/data.duration*w,bot,'#f3b786',1,[4,4]);if(playing||offset){const x=(playing?current():offset)/data.duration*w;line(traceContext,x,top,x,bot,'#f0f4f2',1)} }
function animate(){if(!document.hidden&&active!=='flyby'){if(playing){offset=current();updatePlaybackUI()}drawScene();if(playing)drawTrace()}requestAnimationFrame(animate)}requestAnimationFrame(animate);
function initAtlas(){syncControls()}function syncControls(){for(const key of Object.keys(cfg))cfg[key]={...presets[key],...cfg[key]};showExperiment('flyby');window.addEventListener('pagehide',()=>{pause();sceneObserver.disconnect();traceObserver.disconnect();worker?.terminate()},{once:true});}
export {initAtlas};
